[CmdletBinding()]param([string]$RepositoryRoot=(Resolve-Path(Join-Path $PSScriptRoot '..\..')).Path)
Set-StrictMode -Version 2.0
$ErrorActionPreference='Stop'
$O=Join-Path $RepositoryRoot 'Invoke-MSADPT.ps1';$I=Join-Path $RepositoryRoot 'Modules\SMB\Import-MSADPTNmapSMBTargets.ps1'
foreach($P in @($O,$I)){$T=$null;$E=$null;[void][Management.Automation.Language.Parser]::ParseFile($P,[ref]$T,[ref]$E);if(@($E).Count){throw "ParserFailure[$P]"}}
$Text=[IO.File]::ReadAllText($O);foreach($M in @('$OrchestratorVersion = ''1.7.0''','[string]$SMBNmapXmlPath','SMBNmapXmlPathNotFound','SMBTargetSetEmpty','Ensure the authoritative SMB stage')){if(-not$Text.Contains($M)){throw "ContractMissing: $M"}}
$Temp=Join-Path ([IO.Path]::GetTempPath()) ('MSADPT-NmapTest-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $Temp|Out-Null
try{$Xml='<?xml version="1.0"?><nmaprun><host><status state="up"/><address addr="192.0.2.10" addrtype="ipv4"/><ports><port protocol="tcp" portid="445"><state state="open" reason="syn-ack"/></port></ports></host><host><status state="up"/><address addr="192.0.2.11" addrtype="ipv4"/><ports><port protocol="tcp" portid="445"><state state="filtered" reason="no-response"/></port></ports></host><host><status state="up"/><address addr="192.0.2.12" addrtype="ipv4"/></host></nmaprun>';$X=Join-Path $Temp 'scan.xml';$Xml|Set-Content $X -Encoding UTF8;$R=&$I -NmapXmlPath $X -OutputDirectory (Join-Path $Temp 'out');if($R.ConfirmedOpenTcp445TargetCount-ne1-or$R.Targets[0]-ne'192.0.2.10'){throw 'ImporterSelectionFailed'};$P=@(&$O -Mode Plan -Profile Full -SMBNmapXmlPath $X -NoColor);$PR=@($P|Where-Object{$null-ne$_.PSObject.Properties['Status']})|Select-Object -Last 1;if($PR.Status-ne'Passed'-or$PR.LiveModulesExecuted-ne0){throw 'FullPlanFailed'};[pscustomobject]@{Status='Passed';ConfirmedOpenImported=1;FilteredRejected=2;PlanStatus=$PR.Status;PlanLiveModulesExecuted=$PR.LiveModulesExecuted;NetworkActivity='None'}}finally{Remove-Item $Temp -Recurse -Force -ErrorAction SilentlyContinue}